#!/usr/bin/env python3
from __future__ import annotations

import inspect
import platform
import sys
import types
from pathlib import Path


def _run_impl(source: str, impl_name: str) -> int:
    module_name = f'{__name__}.{impl_name}'
    module = types.ModuleType(module_name)
    module.__file__ = str(Path(__file__).resolve())
    sys.modules[module_name] = module
    namespace = module.__dict__
    exec(compile(source, str(Path(__file__).resolve()), 'exec'), namespace, namespace)
    main_fn = namespace.get('main')
    if not callable(main_fn):
        raise RuntimeError(f"Selected implementation '{impl_name}' for 'genai_parser' does not define main()")
    sig = inspect.signature(main_fn)
    if len(sig.parameters) == 0:
        return int(main_fn())
    if len(sig.parameters) == 1:
        return int(main_fn(sys.argv))
    raise RuntimeError(f"Selected implementation '{impl_name}' for 'genai_parser' has unsupported main() signature")


def main() -> int:
    if platform.system().strip().lower().startswith('win'):
        return _run_impl(_WINDOWS_IMPL, 'windows')
    return _run_impl(_LINUX_IMPL, 'linux')


_LINUX_IMPL = 'from __future__ import annotations\n\nimport csv\nimport re\nimport sys\nfrom pathlib import Path\n\nfrom _linux_common import CONFIG_FILE, load_config, resolve_path\n\n\nDEVICE_RE = re.compile(r"^>> Device:\\s*(.+)$")\nMODEL_DIR_RE = re.compile(r"^>> Model Dir:\\s*(.+)$")\nPIT_RE = re.compile(r"Pipeline initialization time:\\s*([0-9.]+)")\nAVG_RE = re.compile(\n\tr"Input token size:\\s*([0-9.]+).*1st token latency:\\s*([0-9.]+)\\s*ms.*2nd tokens throughput:\\s*([0-9.]+)\\s*tokens/s"\n)\n\n\ndef _missing_hf_report(cfg: dict, project_root: Path) -> list[str]:\n\tlines = ["#", "# === HF MODEL PRESENCE CHECK ==="]\n\tir_dir = cfg.get("ir_dir")\n\tif not ir_dir:\n\t\tlines.append(f"# [Missing ir_dir in {CONFIG_FILE}]")\n\t\treturn lines\n\n\tir_root = resolve_path(str(ir_dir))\n\tmodels = [str(m).strip() for m in (((cfg.get("ir_models") or {}).get("models") or [])) if str(m).strip()]\n\tif not models:\n\t\tlines.append("# [No ir_models entries found; expected ir_models.models[]]")\n\t\treturn lines\n\n\tsel_devices = [str(d).strip().upper() for d in ((cfg.get("defaults") or {}).get("devices") or []) if str(d).strip()]\n\tif not sel_devices:\n\t\tsel_devices = ["GPU", "NPU"]\n\tsel_devices = [d for d in sel_devices if d in {"GPU", "NPU"}]\n\n\tconfigured_count = 0\n\tmissing: list[str] = []\n\tseen: set[str] = set()\n\tfor model in models:\n\t\tstripped = model.split("/", 1)[1] if "/" in model else model\n\t\tsafe = stripped.replace("/", "__")\n\t\tfor device in sel_devices:\n\t\t\texpected = ir_root / device / safe / "openvino_model.xml"\n\t\t\tkey = str(expected)\n\t\t\tif key in seen:\n\t\t\t\tcontinue\n\t\t\tseen.add(key)\n\t\t\tconfigured_count += 1\n\t\t\tif not expected.is_file():\n\t\t\t\tmissing.append(f"{device}/{safe}")\n\n\tlines.append(f"# hf_root: {ir_root}")\n\tlines.append(f"# configured_device_models: {configured_count}")\n\tlines.append(f"# missing_device_models: {len(missing)}")\n\tif not missing:\n\t\tlines.append("# missing_hf_model: NONE")\n\telse:\n\t\tlines.extend(f"# missing_hf_model: {m}" for m in missing)\n\treturn lines\n\n\ndef _parse_rows(text: str) -> list[dict[str, str]]:\n\trows: list[dict[str, str]] = []\n\tcurrent = {\n\t\t"device": "",\n\t\t"model": "",\n\t\t"pit": "",\n\t\t"input_tokens": "",\n\t\t"ttft_ms": "",\n\t\t"tps": "",\n\t}\n\n\tdef flush() -> None:\n\t\tif any(current.values()):\n\t\t\trows.append(current.copy())\n\n\tfor line in text.splitlines():\n\t\tm = DEVICE_RE.match(line)\n\t\tif m:\n\t\t\tflush()\n\t\t\tcurrent = {"device": m.group(1).strip(), "model": "", "pit": "", "input_tokens": "", "ttft_ms": "", "tps": ""}\n\t\t\tcontinue\n\n\t\tm = MODEL_DIR_RE.match(line)\n\t\tif m:\n\t\t\tcurrent["model"] = Path(m.group(1).strip()).name\n\t\t\tcontinue\n\n\t\tm = PIT_RE.search(line)\n\t\tif m and not current["pit"]:\n\t\t\tcurrent["pit"] = m.group(1).strip()\n\t\t\tcontinue\n\n\t\tm = AVG_RE.search(line)\n\t\tif m:\n\t\t\tcurrent["input_tokens"] = m.group(1).strip()\n\t\t\tcurrent["ttft_ms"] = m.group(2).strip()\n\t\t\tcurrent["tps"] = m.group(3).strip()\n\n\tflush()\n\treturn [r for r in rows if any(r.values())]\n\n\ndef main(argv: list[str]) -> int:\n\tif not CONFIG_FILE.is_file():\n\t\tprint(f"Error: Missing config file: {CONFIG_FILE}")\n\t\treturn 1\n\n\tcfg = load_config()\n\tresults_dir_raw = cfg.get("results_dir")\n\tif not results_dir_raw:\n\t\tprint(f"Error: Missing results_dir in {CONFIG_FILE}")\n\t\treturn 1\n\tresults_dir = resolve_path(str(results_dir_raw))\n\tif not results_dir.is_dir():\n\t\tprint(f"Error: Results directory not found: {results_dir}")\n\t\treturn 1\n\n\tinput_file: Path | None = None\n\tif len(argv) > 1:\n\t\tinput_file = Path(argv[1]).resolve()\n\telse:\n\t\tfiles = sorted(results_dir.glob("genaibench_*.txt"), key=lambda p: p.stat().st_mtime, reverse=True)\n\t\tif files:\n\t\t\tinput_file = files[0]\n\n\tif not input_file or not input_file.is_file():\n\t\tprint(f"Error: No genaibench_*.txt found in {results_dir}")\n\t\treturn 1\n\tif not re.match(r"^genaibench_.*\\.txt$", input_file.name):\n\t\tprint("Error: Unsupported input file name. Expected pattern: genaibench_*.txt")\n\t\treturn 1\n\n\toutput_csv = input_file.with_suffix(".csv")\n\ttxt = input_file.read_text(encoding="utf-8", errors="ignore")\n\trows = _parse_rows(txt)\n\tif not rows:\n\t\tprint(f"Error: No benchmark frames found in {input_file}")\n\t\treturn 1\n\n\twith output_csv.open("w", encoding="utf-8", newline="") as fh:\n\t\tfor ln in _missing_hf_report(cfg, Path.cwd()):\n\t\t\tfh.write(f"{ln}\\n")\n\t\tfh.write("\\n")\n\t\twriter = csv.writer(fh)\n\t\twriter.writerow(["Model", "Device", "PIT_s", "InputTokenSize", "TTFT_ms", "TPS"])\n\t\tfor row in rows:\n\t\t\twriter.writerow([row["model"], row["device"], row["pit"], row["input_tokens"], row["ttft_ms"], row["tps"]])\n\n\tprint(f"Input:  {input_file}")\n\tprint(f"Output: {output_csv}")\n\tprint("genai parsing complete.")\n\treturn 0\n\n\nif __name__ == "__main__":\n\traise SystemExit(main(sys.argv))\n'


_WINDOWS_IMPL = 'from __future__ import annotations\n\nimport csv\nimport re\nimport sys\nfrom pathlib import Path\n\nfrom _windows_common_ import latest_matching, load_config, project_root, resolve_path\n\n\ndef build_missing_hf_report(cfg: dict, root: Path) -> list[list[str]]:\n    ir_root = resolve_path(root, cfg.get("ir_dir"), "./MODELS/ir")\n    models = (cfg.get("ir_models") or {}).get("models") or []\n    defaults_devices = (cfg.get("defaults") or {}).get("devices") or []\n    devices = [str(d).strip().upper() for d in defaults_devices if str(d).strip()]\n    if not devices:\n        devices = ["GPU", "NPU"]\n    devices = [d for d in devices if d in {"GPU", "NPU"}]\n\n    configured_count = 0\n    missing_items: list[str] = []\n    seen: set[str] = set()\n\n    for model in models:\n        model = str(model).strip()\n        if not model:\n            continue\n        safe_name = model.split("/", 1)[-1].replace("/", "__")\n        for device in devices:\n            expected = ir_root / device / safe_name / "openvino_model.xml"\n            key = str(expected)\n            if key in seen:\n                continue\n            seen.add(key)\n            configured_count += 1\n            if not expected.is_file():\n                missing_items.append(f"{device}/{safe_name}")\n\n    header_rows = [\n        ["#"],\n        ["# === HF MODEL PRESENCE CHECK ==="],\n        [f"# hf_root: {ir_root}"],\n        [f"# configured_device_models: {configured_count}"],\n        [f"# missing_device_models: {len(missing_items)}"],\n    ]\n\n    if not missing_items:\n        header_rows.append(["# missing_hf_model: NONE"])\n    else:\n        for item in missing_items:\n            header_rows.append([f"# missing_hf_model: {item}"])\n    header_rows.append([])\n    return header_rows\n\n\ndef main() -> int:\n    root = project_root(__file__)\n    cfg = load_config(root)\n    results_dir = resolve_path(root, cfg.get("results_dir"), "./RESULTS")\n    input_file = Path(sys.argv[1]) if len(sys.argv) > 1 else latest_matching(str(results_dir / "genaibench_*.txt"))\n    if not input_file or not input_file.is_file():\n        raise RuntimeError("No genaibench_*.txt found to parse")\n\n    output_csv = input_file.with_suffix(".csv")\n    rows: list[list[str]] = []\n    device = ""\n    model = ""\n    pit = ""\n    ttft = ""\n    tps = ""\n    input_tokens = ""\n\n    with input_file.open("r", encoding="utf-8", errors="ignore") as fh:\n        for raw in fh:\n            line = raw.strip()\n            if line.startswith(">> Device:"):\n                if any([device, model, pit, ttft, tps, input_tokens]):\n                    rows.append([model, device, pit, input_tokens, ttft, tps])\n                device = line.split(":", 1)[1].strip()\n                model = ""\n                pit = ttft = tps = input_tokens = ""\n                continue\n            if line.startswith(">> Model Dir:"):\n                model = Path(line.split(":", 1)[1].strip()).name\n                continue\n\n            m = re.search(r"Pipeline initialization time:\\s*([0-9.]+)", line)\n            if m:\n                pit = m.group(1)\n            m = re.search(r"Input token size:\\s*([0-9]+)", line)\n            if m:\n                input_tokens = m.group(1)\n            m = re.search(r"1st token latency:\\s*([0-9.]+)", line)\n            if m:\n                ttft = m.group(1)\n            m = re.search(r"2nd tokens throughput:\\s*([0-9.]+)", line)\n            if m:\n                tps = m.group(1)\n\n    if any([device, model, pit, ttft, tps, input_tokens]):\n        rows.append([model, device, pit, input_tokens, ttft, tps])\n\n    if not rows:\n        raise RuntimeError(f"No benchmark frames found in {input_file}")\n\n    with output_csv.open("w", newline="", encoding="utf-8") as fh:\n        writer = csv.writer(fh)\n        writer.writerows(build_missing_hf_report(cfg, root))\n        writer.writerow(["Model", "Device", "PIT_s", "InputTokenSize", "TTFT_ms", "TPS"])\n        writer.writerows(rows)\n\n    print(f"Input:  {input_file}")\n    print(f"Output: {output_csv}")\n    return 0\n\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n'


if __name__ == '__main__':
    raise SystemExit(main())
